    public static int productAtKthLevel(Node tree, int k) {
        int level = -1;
        int product = 1;
        int n = tree.children.size();
        for (int i = 0; i < n; i++) {
            if (tree.children.get(i).value.equals(" (")) {
                level++;
            } else if (tree.children.get(i).value.equals(") ")) {
                level--;
